Map<String, String> weaponBehaviorErrors(Map<String, num> values) {
  final errors = <String, String>{};
  for (final rule in weaponBehaviorRelationships) {
    final left = rule["left"] as String, right = rule["right"] as String;
    final a = values[left], b = values[right];
    if (a == null || b == null || !a.isFinite || !b.isFinite) continue;
    if (rule["strict"] == true ? a <= b : a < b) {
      errors[left] = rule["message"] as String;
    }
  }
  return errors;
}
